73	@RestController
74	@CrossOrigin(exposedHeaders = "errors, content-type")
75	@RequestMapping("/api")
76	public class OwnerRestControllerV1 implements OwnersApi {
77	
78	    /**
79	     * Dedicated audit logger. On a successful owner create an audit line carrying the owner id,
80	     * the {@code customerCode} and the {@code registrationDate} is emitted to this named logger.
81	     */
82	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
83	
84	    private final ClinicService clinicService;
85	
86	    private final OwnerMapper ownerMapper;
87	
88	    private final PetMapper petMapper;
89	
90	    private final VisitMapper visitMapper;
91	
92	    public OwnerRestControllerV1(ClinicService clinicService,
93	                                 OwnerMapper ownerMapper,
94	                                 PetMapper petMapper,
95	                                 VisitMapper visitMapper) {
96	        this.clinicService = clinicService;
97	        this.ownerMapper = ownerMapper;
98	        this.petMapper = petMapper;
99	        this.visitMapper = visitMapper;
100	    }
101	
102	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
103	    @Override
104	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
105	        Collection<Owner> owners;
106	        if (lastName != null) {
107	            owners = this.clinicService.findOwnerByLastName(lastName);
108	        } else {
109	            owners = this.clinicService.findAllOwners();
110	        }
111	        if (owners.isEmpty()) {
112	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
113	        }
114	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
115	    }
116	
117	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
118	    @Override
119	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
120	        Owner owner = this.clinicService.findOwnerById(ownerId);
121	        if (owner == null) {
122	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
123	        }
124	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
125	    }
126	
127	    /**
128	     * Rejects an owner payload that is missing or blank in any of the required fields
129	     * (firstName, lastName, address, city, telephone). Bean Validation on the request body
130	     * already rejects {@code null} values and empty strings, but treats a whitespace-only
131	     * value as present; this guard closes that gap so a blank in any required field is
132	     * reported. The thrown exception is translated to a 400 whose {@code errors} array lists
133	     * the name of each offending field.
134	     */
135	    private void rejectMissingOrBlankFields(OwnerFieldsDto ownerFieldsDto, String normalizedAddress) {
136	        List<String> missing = new ArrayList<>();
137	        if (isBlank(ownerFieldsDto.getFirstName())) {
138	            missing.add("firstName");
139	        }
140	        if (isBlank(ownerFieldsDto.getLastName())) {
141	            missing.add("lastName");
142	        }
143	        if (isBlank(normalizedAddress)) {
144	            missing.add("address");
145	        }
146	        if (isBlank(ownerFieldsDto.getCity())) {
147	            missing.add("city");
148	        }
149	        if (isBlank(ownerFieldsDto.getTelephone())) {
150	            missing.add("telephone");
151	        }
152	        if (!missing.isEmpty()) {
153	            throw new MissingOwnerFieldsException(missing);
154	        }
155	    }
156	
157	    private static boolean isBlank(String value) {
158	        return value == null || value.isBlank();
159	    }
160	
161	    /**
162	     * Matches a well-formed E.164 telephone: a leading '+' followed by 8 to 15 digits.
163	     */
164	    private static final Pattern E164_PATTERN = Pattern.compile("\\+\\d{8,15}");
165	
166	    /**
167	     * Required national-number length per country calling code. When the normalized E.164 number
168	     * begins with one of these codes, the digits that follow must number exactly the mapped value:
169	     * '+61' (Australia) requires 9 national digits and '+1' (NANP) requires 10. Codes absent from
170	     * this map carry no per-country length rule beyond the generic E.164 8-to-15-digit bound.
171	     */
172	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = Map.of(
173	        "+61", 9,
174	        "+1", 10);
175	
176	    /**
177	     * Normalizes an owner's telephone on create into E.164 form. Spaces, dashes and brackets are
178	     * stripped. When a leading '+' (with its country code) is present it is kept as-is; otherwise
179	     * the country code '+61' is assumed and a single leading '0' is dropped from the national
180	     * digits. The result must be a '+' followed by 8 to 15 digits, so e.g. '0412 345 678' is
181	     * stored as '+61412345678'. When the country code has a known national-number length ('+61'
182	     * requires 9 national digits, '+1' requires 10) the national digits must match it exactly. A
183	     * value that cannot form a valid E.164 number, or whose national length is wrong for its
184	     * country, is rejected via {@link InvalidTelephoneException}, which the exception handler
185	     * translates to a 400.
186	     */
187	    private static String normalizeTelephone(String telephone) {
188	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()\\[\\]]", "");
189	        String e164;
190	        if (cleaned.startsWith("+")) {
191	            e164 = cleaned;
192	        } else {
193	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
194	            e164 = "+61" + national;
195	        }
196	        if (!E164_PATTERN.matcher(e164).matches()) {
197	            throw new InvalidTelephoneException(telephone);
198	        }
199	        for (Map.Entry<String, Integer> rule : NATIONAL_NUMBER_LENGTHS.entrySet()) {
200	            String code = rule.getKey();
201	            if (e164.startsWith(code)) {
202	                int nationalLength = e164.length() - code.length();
203	                if (nationalLength != rule.getValue()) {
204	                    throw new InvalidTelephoneException(telephone);
205	                }
206	                break;
207	            }
208	        }
209	        return e164;
210	    }
211	
212	    /**
213	     * Matches a well-formed postcode: exactly four digits.
214	     */
215	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("\\d{4}");
216	
217	    /**
218	     * The canonical region for each city that has one. A city absent from this table has no known
219	     * region and so accepts any 4-digit postcode. This is the same fixed city-to-region table used
220	     * to derive an owner's locality.
221	     */
222	    private static final Map<String, String> CITY_REGION = Map.of(
223	        "Sydney", "NSW",
224	        "Melbourne", "VIC",
225	        "Brisbane", "QLD");
226	
227	    /**
228	     * The inclusive 4-digit postcode range for each region, as {@code {low, high}}: NSW 2000-2099,
229	     * VIC 3000-3099, QLD 4000-4099.
230	     */
231	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
232	        "NSW", new int[] {2000, 2099},
233	        "VIC", new int[] {3000, 3099},
234	        "QLD", new int[] {4000, 4099});
235	
236	    /**
237	     * Validates an owner's optional postcode. A {@code null} postcode is left as-is (the field is
238	     * optional). When present it must be exactly four digits; and when the owner's city maps to a
239	     * known region it must fall within that region's inclusive postcode range (NSW 2000-2099, VIC
240	     * 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit postcode. An
241	     * invalid or out-of-range value is rejected via {@link InvalidPostcodeException}, which the
242	     * exception handler translates to a 400.
243	     */
244	    private static void validatePostcode(String city, String postcode) {
245	        if (postcode == null) {
246	            return;
247	        }
248	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
249	            throw new InvalidPostcodeException(postcode);
250	        }
251	        String region = CITY_REGION.get(city);
252	        if (region == null) {
253	            return;
254	        }
255	        int[] range = REGION_POSTCODES.get(region);
256	        int value = Integer.parseInt(postcode);
257	        if (value < range[0] || value > range[1]) {
258	            throw new InvalidPostcodeException(postcode);
259	        }
260	    }
261	
262	    /**
263	     * A pragmatic syntactic email check: a non-empty local part, an {@code @}, and a domain that
264	     * carries at least one dot, with no whitespace anywhere. Deliberately permissive — it accepts
265	     * ordinary addresses while rejecting obvious non-addresses such as one lacking an {@code @}.
266	     */
267	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
268	
269	    /**
270	     * Disposable-email domains that an owner's email may not use. An address whose domain (the part
271	     * after the final {@code @}, compared case-insensitively) is one of these is rejected. Kept as a
272	     * fixed set so the block list is explicit and easy to extend.
273	     */
274	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
275	        "mailinator.com",
276	        "tempmail.com",
277	        "guerrillamail.com");
278	
279	    /**
280	     * Normalizes an optional owner email. A {@code null} email is left as-is (the field is
281	     * optional). When present it must be a syntactically valid address whose domain is not on the
282	     * disposable-domain block list; a valid value is lower-cased so it is stored and returned in
283	     * canonical form. An invalid or disposable-domain value is rejected via
284	     * {@link InvalidEmailException}, which the exception handler translates to a 400.
285	     */
286	    private static String normalizeEmail(String email) {
287	        if (email == null) {
288	            return null;
289	        }
290	        if (!EMAIL_PATTERN.matcher(email).matches()) {
291	            throw new InvalidEmailException(email);
292	        }
293	        String normalized = email.toLowerCase(Locale.ROOT);
294	        String domain = normalized.substring(normalized.lastIndexOf('@') + 1);
295	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
296	            throw new InvalidEmailException(email);
297	        }
298	        return normalized;
299	    }
300	
301	    /**
302	     * The single derived identity of an owner, {@code normalizedTelephone + '|' + (email or empty)
303	     * + '|' + householdId}, into which all duplicate detection is consolidated. Two owners are the
304	     * same identity only when this whole key matches: because the normalized telephone is part of
305	     * the key, two members of the same household (same {@code householdId}) with different
306	     * telephones have different identity keys. A {@code null} email contributes an empty middle
307	     * segment. This is the value returned to callers as {@code identityKey}.
308	     */
309	    private static String identityKeyFor(String normalizedTelephone, String normalizedEmail, String householdId) {
310	        return normalizedTelephone + "|" + (normalizedEmail == null ? "" : normalizedEmail) + "|" + householdId;
311	    }
312	
313	    /**
314	     * Rejects a create whose derived identity collides with an existing owner's, reported via one
315	     * of the {@code Duplicate*} exceptions the handler translates to a 409. The former separate
316	     * telephone, email and household checks are now expressed through the components of the single
317	     * identity key:
318	     * <ul>
319	     *   <li>the normalized telephone matches an existing owner's canonical E.164 telephone (an
320	     *       existing value that cannot form a valid E.164 number is skipped rather than colliding);</li>
321	     *   <li>a present, lower-cased email matches an existing owner's lower-cased email (a {@code null}
322	     *       candidate email, being optional, is not compared, and existing owners without an email
323	     *       are skipped);</li>
324	     *   <li>the {@code householdId} matches an existing owner's - unless the caller opted into sharing
325	     *       a household via {@code sharesHousehold}, in which case the household component is not
326	     *       compared.</li>
327	     * </ul>
328	     */
329	    private void rejectDuplicateIdentity(OwnerFieldsDto ownerFieldsDto, String normalizedTelephone,
330	                                         String normalizedEmail, String householdId) {
331	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
332	        for (Owner existing : this.clinicService.findAllOwners()) {
333	            String existingTelephone;
334	            try {
335	                existingTelephone = normalizeTelephone(existing.getTelephone());
336	            } catch (InvalidTelephoneException ex) {
337	                existingTelephone = null;
338	            }
339	            if (normalizedTelephone.equals(existingTelephone)) {
340	                throw new DuplicateTelephoneException(normalizedTelephone);
341	            }
342	            if (normalizedEmail != null) {
343	                String existingEmail = existing.getEmail();
344	                if (existingEmail != null && normalizedEmail.equals(existingEmail.toLowerCase(Locale.ROOT))) {
345	                    throw new DuplicateEmailException(normalizedEmail);
346	                }
347	            }
348	            if (!sharesHousehold
349	                && householdId.equals(householdIdFor(existing.getLastName(), existing.getPostcode()))) {
350	                throw new DuplicateHouseholdException(ownerFieldsDto.getLastName(), ownerFieldsDto.getPostcode());
351	            }
352	        }
353	    }
354	
355	    /**
356	     * Collapses a value for household comparison: leading and trailing whitespace is trimmed, any
357	     * internal run of whitespace is reduced to a single space, and the result is lower-cased. This
358	     * is how both {@code lastName} and {@code address} are compared so that differences of case or
359	     * spacing do not defeat the duplicate-household check.
360	     */
361	    private static String collapse(String value) {
362	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
363	    }
364	
365	    /**
366	     * Normalizes an owner's address into a canonical form applied on every create: leading and
367	     * trailing whitespace is trimmed, any internal run of whitespace is reduced to a single space,
368	     * the value is upper-cased, and common street-type abbreviations are expanded on a per-word
369	     * basis ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). The result is stored
370	     * and returned, and is the form every address comparison (duplicate-household detection and the
371	     * shared {@code householdId}) uses. A {@code null} or whitespace-only input normalizes to the
372	     * empty string, which the required-field guard then rejects. The transformation is idempotent,
373	     * so normalizing an already-normalized address is a no-op.
374	     */
375	    private static String normalizeAddress(String address) {
376	        if (address == null) {
377	            return "";
378	        }
379	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
380	        if (collapsed.isEmpty()) {
381	            return "";
382	        }
383	        String[] tokens = collapsed.split(" ");
384	        StringBuilder sb = new StringBuilder(collapsed.length());
385	        for (int i = 0; i < tokens.length; i++) {
386	            String token = tokens[i];
387	            switch (token) {
388	                case "ST" -> token = "STREET";
389	                case "RD" -> token = "ROAD";
390	                case "AVE" -> token = "AVENUE";
391	                default -> {
392	                }
393	            }
394	            if (i > 0) {
395	                sb.append(' ');
396	            }
397	            sb.append(token);
398	        }
399	        return sb.toString();
400	    }
401	
402	    /**
403	     * Derives an owner's region code from its postcode, falling back to its city. A present postcode
404	     * that falls in a known region's inclusive 4-digit range wins (NSW 2000-2099, VIC 3000-3099, QLD
405	     * 4000-4099); otherwise the fixed city-to-region table is consulted (Sydney -> NSW, Melbourne ->
406	     * VIC, Brisbane -> QLD); a value resolved by neither is {@code "UNKNOWN"}. This is the single
407	     * region derivation shared by the {@code customerCode} and the owner's locality.
408	     */
409	    private static String deriveRegion(String city, String postcode) {
410	        if (postcode != null) {
411	            try {
412	                int pc = Integer.parseInt(postcode.trim());
413	                for (Map.Entry<String, int[]> range : REGION_POSTCODES.entrySet()) {
414	                    int[] bounds = range.getValue();
415	                    if (pc >= bounds[0] && pc <= bounds[1]) {
416	                        return range.getKey();
417	                    }
418	                }
419	            } catch (NumberFormatException ignored) {
420	                // not a numeric postcode; fall back to the city-to-region table
421	            }
422	        }
423	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
424	    }
425	
426	    /**
427	     * Builds the {@code customerCode} for a newly created owner, formatted {@code '<REGION>-<HASH8>'}
428	     * where {@code REGION} is the region code derived from the owner's postcode (falling back to its
429	     * city) and {@code HASH8} is the first 8 upper-case hex characters of SHA-256 over
430	     * {@code normalizedTelephone + lastName} (e.g. {@code 'NSW-1A2B3C4D'}). This is a stable identity:
431	     * it carries no sequence number and depends only on the owner's own region, telephone and surname.
432	     */
433	    private static String customerCodeFor(String region, String normalizedTelephone, String lastName) {
434	        return region + "-" + sha256HexPrefix(normalizedTelephone + lastName, 8);
435	    }
436	
437	    /**
438	     * Returns the first {@code hexChars} upper-case hex characters of the SHA-256 digest of the UTF-8
439	     * bytes of {@code value}.
440	     */
441	    private static String sha256HexPrefix(String value, int hexChars) {
442	        try {
443	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
444	            StringBuilder sb = new StringBuilder(hexChars);
445	            for (byte b : digest) {
446	                if (sb.length() >= hexChars) {
447	                    break;
448	                }
449	                sb.append(String.format("%02X", b));
450	            }
451	            return sb.substring(0, hexChars);
452	        } catch (NoSuchAlgorithmException ex) {
453	            throw new IllegalStateException("SHA-256 not available", ex);
454	        }
455	    }
456	
457	    /**
458	     * Builds the {@code membershipNumber} for a newly created owner, formatted
459	     * {@code '<customerCode>-M<YY>'} where {@code YY} is the last two digits of the
460	     * {@code registrationDate} year (e.g. {@code 'SMI-0007-M26'}).
461	     */
462	    private static String membershipNumberFor(String customerCode, LocalDate registrationDate) {
463	        return String.format("%s-M%02d", customerCode, registrationDate.getYear() % 100);
464	    }
465	
466	    /**
467	     * Derives the stable {@code householdId} for an owner from the collapsed {@code lastName} and
468	     * its {@code postcode} - the same pair used to detect a shared household. It is the first 12
469	     * lower-case hex characters of SHA-256 over {@code normalizedLastName + '|' + postcode}. Because
470	     * it is a pure function of that pair, every owner in the same household - whether created first
471	     * or joining later via {@code sharesHousehold} - receives the identical, non-blank identifier
472	     * without needing to read any other owner's value. A {@code null} postcode contributes an empty
473	     * segment.
474	     */
475	    private static String householdIdFor(String lastName, String postcode) {
476	        String key = collapse(lastName) + "|" + (postcode == null ? "" : postcode);
477	        try {
478	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
479	            StringBuilder sb = new StringBuilder(12);
480	            for (byte b : digest) {
481	                if (sb.length() >= 12) {
482	                    break;
483	                }
484	                sb.append(String.format("%02x", b));
485	            }
486	            return sb.substring(0, 12);
487	        } catch (NoSuchAlgorithmException ex) {
488	            throw new IllegalStateException("SHA-256 not available", ex);
489	        }
490	    }
491	
492	    /**
493	     * Counts the existing owners who already share the given {@code firstName} and {@code lastName},
494	     * compared case-insensitively. This is evaluated before the new owner is saved, so it reflects
495	     * the state prior to this create and is stored on the owner as its {@code namesakeCount}.
496	     */
497	    private int countNamesakes(String firstName, String lastName) {
498	        int count = 0;
499	        for (Owner existing : this.clinicService.findAllOwners()) {
500	            if (firstName.equalsIgnoreCase(existing.getFirstName())
501	                && lastName.equalsIgnoreCase(existing.getLastName())) {
502	                count++;
503	            }
504	        }
505	        return count;
506	    }
507	
508	    /**
509	     * Counts the members of the household the new owner will belong to, as it stands after this
510	     * create. Every existing owner carrying the same {@code householdId} is counted, and the new
511	     * owner itself is added, so a value of 3 or more means the owner joins a household of at least
512	     * three members. This is evaluated with the new owner's {@code householdId} already set and is
513	     * stored on the owner as its {@code householdMemberCount}.
514	     */
515	    private int countHouseholdMembers(String householdId) {
516	        int count = 1;
517	        for (Owner existing : this.clinicService.findAllOwners()) {
518	            if (householdId.equals(existing.getHouseholdId())) {
519	                count++;
520	            }
521	        }
522	        return count;
523	    }
524	
525	    /**
526	     * Finds an existing owner that makes the new owner a <em>possible</em> (soft) duplicate: one
527	     * that is not a hard identity collision but shares the new owner's {@code lastName} (compared
528	     * case-insensitively) and {@code postcode} while carrying a different normalized telephone. The
529	     * new owner's postcode must be present for a soft match to be possible. When several existing
530	     * owners qualify the one with the lowest id is chosen. Returns the matching owner's id, or
531	     * {@code null} when there is no soft match. This is evaluated after the hard-duplicate check has
532	     * already passed, so any owner sharing the lastName and postcode necessarily differs in telephone.
533	     *
534	     * <p>Because the household is now keyed on {@code (lastName, postcode)} - exactly the soft-match
535	     * key - a co-member reached here can only be one the caller declared via {@code sharesHousehold}
536	     * (otherwise the hard household-duplicate check would already have rejected it). A declared
537	     * household member is not a suspected duplicate, so no soft match is reported in that case.
538	     */
539	    private Integer findPossibleDuplicateOf(OwnerFieldsDto ownerFieldsDto, String normalizedTelephone) {
540	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
541	            return null;
542	        }
543	        String postcode = ownerFieldsDto.getPostcode();
544	        if (postcode == null) {
545	            return null;
546	        }
547	        String lastName = ownerFieldsDto.getLastName();
548	        Integer matchId = null;
549	        for (Owner existing : this.clinicService.findAllOwners()) {
550	            if (lastName == null || !lastName.equalsIgnoreCase(existing.getLastName())) {
551	                continue;
552	            }
553	            if (!postcode.equals(existing.getPostcode())) {
554	                continue;
555	            }
556	            String existingTelephone;
557	            try {
558	                existingTelephone = normalizeTelephone(existing.getTelephone());
559	            } catch (InvalidTelephoneException ex) {
560	                existingTelephone = null;
561	            }
562	            if (normalizedTelephone.equals(existingTelephone)) {
563	                continue;
564	            }
565	            if (existing.getId() != null && (matchId == null || existing.getId() < matchId)) {
566	                matchId = existing.getId();
567	            }
568	        }
569	        return matchId;
570	    }
571	
572	    /**
573	     * The tenure, in days, that an owner must exceed before its tenure contributes membership
574	     * points. Tenure is measured from the owner's {@code registrationDate}, so a newly created owner
575	     * (whose tenure is zero) never satisfies this and thus never earns the tenure points on create.
576	     */
577	    private static final int TENURE_POINTS_THRESHOLD_DAYS = 365;
578	
579	    /**
580	     * The household size (number of members) at or above which an owner earns the household points.
581	     */
582	    private static final int HOUSEHOLD_POINTS_THRESHOLD = 3;
583	
584	    /**
585	     * Computes the {@code membershipPoints} for an owner. Points start at 0, gain 2 when an email is
586	     * present, gain 1 when the owner's {@code namesakeCount} is 0, gain 2 when the owner's household
587	     * has {@value #HOUSEHOLD_POINTS_THRESHOLD} or more members, and gain 3 when the owner's tenure
588	     * (days elapsed since its {@code registrationDate}) exceeds {@value #TENURE_POINTS_THRESHOLD_DAYS}
589	     * days. Because a newly created owner has zero tenure, the tenure points never apply on create.
590	     * Evaluated after the owner's email, namesakeCount, householdMemberCount and registrationDate
591	     * have been set.
592	     */
593	    private static int membershipPointsFor(Owner owner) {
594	        int points = 0;
595	        if (owner.getEmail() != null && !owner.getEmail().isEmpty()) {
596	            points += 2;
597	        }
598	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
599	            points += 1;
600	        }
601	        if (owner.getHouseholdMemberCount() != null
602	            && owner.getHouseholdMemberCount() >= HOUSEHOLD_POINTS_THRESHOLD) {
603	            points += 2;
604	        }
605	        if (tenureInDays(owner) > TENURE_POINTS_THRESHOLD_DAYS) {
606	            points += 3;
607	        }
608	        return points;
609	    }
610	
611	    /**
612	     * Maps {@code membershipPoints} to the numeric {@code membershipLevel}: level 1 for 0-1 points,
613	     * 2 for 2-3, 3 for 4-5, and 4 for 6 or more points.
614	     */
615	    private static int membershipLevelForPoints(int points) {
616	        if (points <= 1) {
617	            return 1;
618	        }
619	        if (points <= 3) {
620	            return 2;
621	        }
622	        if (points <= 5) {
623	            return 3;
624	        }
625	        return 4;
626	    }
627	
628	    /**
629	     * The owner's tenure in whole days: the number of days elapsed from its {@code registrationDate}
630	     * up to the current server date. An owner with no registration date, or one dated in the future,
631	     * has a tenure of zero.
632	     */
633	    private static long tenureInDays(Owner owner) {
634	        LocalDate registrationDate = owner.getRegistrationDate();
635	        if (registrationDate == null) {
636	            return 0;
637	        }
638	        return Math.max(0, ChronoUnit.DAYS.between(registrationDate, LocalDate.now()));
639	    }
640	
641	    /**
642	     * The maximum number of owners any single city may contain. A create whose city already
643	     * holds this many owners is rejected.
644	     */
645	    private static final int CITY_CAPACITY = 50;
646	
647	    /**
648	     * Rejects a create whose city already contains {@value #CITY_CAPACITY} or more owners,
649	     * compared case-insensitively - the same way the city is matched when building the
650	     * {@code customerCode} sequence. The count reflects the state prior to this create. A city
651	     * at capacity is reported via {@link CityAtCapacityException}, which the exception handler
652	     * translates to a 409.
653	     */
654	    private void rejectCityAtCapacity(String city) {
655	        int count = 0;
656	        for (Owner existing : this.clinicService.findAllOwners()) {
657	            if (city.equalsIgnoreCase(existing.getCity())) {
658	                count++;
659	            }
660	        }
661	        if (count >= CITY_CAPACITY) {
662	            throw new CityAtCapacityException(city);
663	        }
664	    }
665	
666	    /**
667	     * The maximum number of owners that may be created on any single day (by
668	     * {@code registrationDate}). A create attempted once this many owners already carry the
669	     * current day's registration date is rejected.
670	     */
671	    private static final int DAILY_OWNER_LIMIT = 100;
672	
673	    /**
674	     * Rejects a create once {@value #DAILY_OWNER_LIMIT} or more owners already carry the given
675	     * business-day-adjusted {@code registrationDate} (the date the new owner will itself receive).
676	     * The count reflects the state prior to this create. When the limit is reached the create is
677	     * reported via {@link DailyOwnerLimitExceededException}, which the exception handler translates
678	     * to a 429 Too Many Requests.
679	     */
680	    private void rejectDailyOwnerLimit(LocalDate registrationDate) {
681	        int count = 0;
682	        for (Owner existing : this.clinicService.findAllOwners()) {
683	            if (registrationDate.equals(existing.getRegistrationDate())) {
684	                count++;
685	            }
686	        }
687	        if (count >= DAILY_OWNER_LIMIT) {
688	            throw new DailyOwnerLimitExceededException();
689	        }
690	    }
691	
692	    /**
693	     * The number of owners that must already carry a given {@code registrationDate} before a
694	     * create on that date is flagged with a bulk-signup warning. Once <em>more than</em> this
695	     * many owners already exist for the day, the new owner's {@code bulkSignupWarning} is true.
696	     */
697	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
698	
699	    /**
700	     * Computes the {@code bulkSignupWarning} for a create on the given business-day-adjusted
701	     * {@code registrationDate}: true when more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners
702	     * have already been created for that date, otherwise false. The count reflects the state prior
703	     * to this create, matching how the daily-limit rule accumulates.
704	     */
705	    private boolean bulkSignupWarningFor(LocalDate registrationDate) {
706	        int count = 0;
707	        for (Owner existing : this.clinicService.findAllOwners()) {
708	            if (registrationDate.equals(existing.getRegistrationDate())) {
709	                count++;
710	            }
711	        }
712	        return count > BULK_SIGNUP_WARNING_THRESHOLD;
713	    }
714	
715	    /**
716	     * Rolls an effective registration date forward onto a business day. A Saturday or Sunday is
717	     * advanced to the following Monday; a weekday is returned unchanged. This is applied to the
718	     * effective registration date - whether supplied in the request or defaulted to the server
719	     * date - so the stored {@code registrationDate}, and everything derived from it, always falls
720	     * on a business day.
721	     */
722	    /**
723	     * Rejects a supplied {@code registrationDate} that lies in the future. A registration date is
724	     * only ever explicitly supplied on the request; when present it must not be later than the
725	     * current server date. A future date raises a {@link FutureRegistrationDateException}, which the
726	     * exception handler translates to a 400 Bad Request. A {@code null} date (the default, filled in
727	     * later from the server date) is accepted.
728	     */
729	    private static void rejectFutureRegistrationDate(LocalDate registrationDate) {
730	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
731	            throw new FutureRegistrationDateException(registrationDate);
732	        }
733	    }
734	
735	    private static LocalDate toBusinessDay(LocalDate date) {
736	        return switch (date.getDayOfWeek()) {
737	            case SATURDAY -> date.plusDays(2);
738	            case SUNDAY -> date.plusDays(1);
739	            default -> date;
740	        };
741	    }
