743	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
744	    @Override
745	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
746	        String normalizedAddress = normalizeAddress(ownerFieldsDto.getAddress());
747	        rejectMissingOrBlankFields(ownerFieldsDto, normalizedAddress);
748	        rejectCityAtCapacity(ownerFieldsDto.getCity());
749	        HttpHeaders headers = new HttpHeaders();
750	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
751	        owner.setAddress(normalizedAddress);
752	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
753	        owner.setTelephone(normalizedTelephone);
754	        String normalizedEmail = normalizeEmail(ownerFieldsDto.getEmail());
755	        owner.setEmail(normalizedEmail);
756	        validatePostcode(owner.getCity(), owner.getPostcode());
757	        String householdId = householdIdFor(owner.getLastName(), owner.getPostcode());
758	        rejectDuplicateIdentity(ownerFieldsDto, normalizedTelephone, normalizedEmail, householdId);
759	        rejectFutureRegistrationDate(owner.getRegistrationDate());
760	        LocalDate effectiveDate = owner.getRegistrationDate() == null ? LocalDate.now() : owner.getRegistrationDate();
761	        LocalDate registrationDate = toBusinessDay(effectiveDate);
762	        rejectDailyOwnerLimit(registrationDate);
763	        owner.setBulkSignupWarning(bulkSignupWarningFor(registrationDate));
764	        owner.setRegistrationDate(registrationDate);
765	        String region = deriveRegion(owner.getCity(), owner.getPostcode());
766	        owner.setCustomerCode(customerCodeFor(region, normalizedTelephone, owner.getLastName()));
767	        owner.setMembershipNumber(membershipNumberFor(owner.getCustomerCode(), owner.getRegistrationDate()));
768	        owner.setHouseholdId(householdId);
769	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
770	        owner.setHouseholdMemberCount(countHouseholdMembers(owner.getHouseholdId()));
771	        int membershipPoints = membershipPointsFor(owner);
772	        owner.setMembershipPoints(membershipPoints);
773	        owner.setMembershipLevel(membershipLevelForPoints(membershipPoints));
774	        Integer possibleDuplicateOf = findPossibleDuplicateOf(ownerFieldsDto, normalizedTelephone);
775	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
776	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
777	        this.clinicService.saveOwner(owner);
778	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
779	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel());
780	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
781	        headers.setLocation(UriComponentsBuilder.newInstance()
782	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
783	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
784	    }
