50	    /**
51	     * Derive the owner's locality (region) from its region-and-hash {@code customerCode}: the
52	     * {@code REGION} portion is the segment before the first {@code '-'} (e.g. {@code "NSW-1A2B3C4D"}
53	     * yields {@code "NSW"}). This shares the identity's region derivation, where the postcode range
54	     * takes precedence (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099) and the city-to-region table is
55	     * the fallback. For an owner without a {@code customerCode} the same region is recomputed directly
56	     * from the postcode then city, otherwise "UNKNOWN".
57	     */
58	    default String deriveLocality(Owner owner) {
59	        if (owner == null) {
60	            return null;
61	        }
62	        String customerCode = owner.getCustomerCode();
63	        if (customerCode != null) {
64	            int dash = customerCode.indexOf('-');
65	            if (dash > 0) {
66	                return customerCode.substring(0, dash);
67	            }
68	        }
69	        String postcode = owner.getPostcode();
70	        if (postcode != null) {
71	            try {
72	                int pc = Integer.parseInt(postcode.trim());
73	                if (pc >= 2000 && pc <= 2099) {
74	                    return "NSW";
75	                }
76	                if (pc >= 3000 && pc <= 3099) {
77	                    return "VIC";
78	                }
79	                if (pc >= 4000 && pc <= 4099) {
80	                    return "QLD";
81	                }
82	            }
83	            catch (NumberFormatException ignored) {
84	                // not a numeric postcode; fall back to the city-to-region table
85	            }
86	        }
87	        String city = owner.getCity();
88	        if ("Sydney".equals(city)) {
89	            return "NSW";
90	        }
91	        if ("Melbourne".equals(city)) {
92	            return "VIC";
93	        }
94	        if ("Brisbane".equals(city)) {
95	            return "QLD";
96	        }
97	        return "UNKNOWN";
98	    }
99	
100	    /**
101	     * Derive the owner's check digit: a single Luhn check digit (0-9) computed over the
102	     * digits contained in the owner's customerCode. Non-digit characters are ignored.
103	     * Returns null when the owner or its customerCode is absent.
104	     */
105	    default Integer deriveCheckDigit(Owner owner) {
106	        if (owner == null || owner.getCustomerCode() == null) {
107	            return null;
108	        }
109	        String code = owner.getCustomerCode();
110	        int sum = 0;
111	        boolean dbl = true;
112	        for (int i = code.length() - 1; i >= 0; i--) {
113	            char c = code.charAt(i);
114	            if (c < '0' || c > '9') {
115	                continue;
116	            }
117	            int d = c - '0';
118	            if (dbl) {
119	                d *= 2;
120	                if (d > 9) {
121	                    d -= 9;
122	                }
123	            }
124	            sum += d;
125	            dbl = !dbl;
126	        }
127	        return (10 - (sum % 10)) % 10;
128	    }
129	
130	    /**
131	     * Derive the owner's age band from its birthDate against the registrationDate: 'MINOR' when
132	     * under 18, 'ADULT' from 18 to 64, and 'SENIOR' at 65 or older. The age is the number of whole
133	     * years between birthDate and registrationDate (falling back to the current date when the owner
134	     * has no registrationDate). Returns null when the owner or its birthDate is absent, so no
135	     * ageBand is reported.
136	     */
137	    default String deriveAgeBand(Owner owner) {
138	        if (owner == null || owner.getBirthDate() == null) {
139	            return null;
140	        }
141	        java.time.LocalDate reference = owner.getRegistrationDate() != null
142	            ? owner.getRegistrationDate() : java.time.LocalDate.now();
143	        int age = java.time.Period.between(owner.getBirthDate(), reference).getYears();
144	        if (age < 18) {
145	            return "MINOR";
146	        }
147	        if (age < 65) {
148	            return "ADULT";
149	        }
150	        return "SENIOR";
151	    }
152	
153	    /**
154	     * Known E.164 country calling codes, longest first, used to split a stored telephone into its
155	     * country code and national digits. A number whose code is not listed falls back to a two-digit
156	     * country code, the most common E.164 length.
157	     */
158	    String[] KNOWN_CALLING_CODES = { "61", "1" };
159	
160	    /**
161	     * Format the owner's stored E.164 {@code telephone} for humans: the country code, a space, then
162	     * the national digits grouped in threes (e.g. {@code "+61412345678"} becomes
163	     * {@code "+61 412 345 678"}). Returns null when the owner or its telephone is absent, and returns
164	     * the value unchanged when it is not in E.164 form.
165	     */
166	    default String deriveTelephoneDisplay(Owner owner) {
167	        if (owner == null || owner.getTelephone() == null) {
168	            return null;
169	        }
170	        String telephone = owner.getTelephone();
171	        if (!telephone.startsWith("+")) {
172	            return telephone;
173	        }
174	        String digits = telephone.substring(1);
175	        int codeLength = 2;
176	        for (String code : KNOWN_CALLING_CODES) {
177	            if (digits.startsWith(code) && digits.length() > code.length()) {
178	                codeLength = code.length();
179	                break;
180	            }
181	        }
182	        if (digits.length() <= codeLength) {
183	            return telephone;
184	        }
185	        String national = digits.substring(codeLength);
186	        StringBuilder display = new StringBuilder("+").append(digits, 0, codeLength);
187	        for (int i = 0; i < national.length(); i += 3) {
188	            display.append(' ').append(national, i, Math.min(i + 3, national.length()));
189	        }
190	        return display.toString();
191	    }
192	
193	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
194	        OwnerPageDto ownerPageDto = new OwnerPageDto();
195	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
196	        ownerPageDto.setPage(ownerPage.getNumber());
197	        ownerPageDto.setSize(ownerPage.getSize());
198	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
199	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
200	        return ownerPageDto;
201	    }
202	}
